            .iter()
            .map(|(short, versions)| {
                Ok((
                    short.clone(),
                    versions
                        .iter()
                        .map(lockfile_tool_from_tool_version)
                        .collect::<Result<Vec<_>>>()?,
                ))
            })
            .collect::<Result<_>>()?;

